import{_ as o,C as a,o as r,c as n,E as i,a2 as s}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse(`{"title":"Multi-Horizon Work Needs a Runtime, Not a Larger Context Window","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"Multi-Horizon Work Needs a Runtime, Not a Larger Context Window","date":"2026-08-12","column":"digital-employee","category":"academic","article_type":"technical-analysis","edition":"research-center","research_question":"What architectural claims are actually supported by CorpGen's published evidence for concurrent multi-horizon work, and which parts remain hypotheses for production Digital Employee runtimes?","summary":"Microsoft Research's CorpGen study suggests that concurrent long-horizon agent work is best treated as an explicit scheduling, isolation, memory and evaluation problem rather than one ever-growing context, while its controlled benchmark leaves production reliability and independent validation unresolved.","sources":"arXiv:2602.14229; Microsoft Research CorpGen publication and technical article; research/reading/Q-20260803-09-corpgen-multi-horizon.md; research/analysis/Q-20260803-09-corpgen-multi-horizon.md","cover":"/assets/covers/academic-corpgen-multi-horizon-cover-v2.png"},"headers":[],"relativePath":"en/digital-employee/2026-08-12-corpgen-multi-horizon-runtime.md","filePath":"en/digital-employee/2026-08-12-corpgen-multi-horizon-runtime.md","lastUpdated":1787389481000}`),l={name:"en/digital-employee/2026-08-12-corpgen-multi-horizon-runtime.md"};function c(h,e,d,u,p,m){const t=a("ArticleCover");return r(),n("div",null,[i(t,{image:"/assets/covers/academic-corpgen-multi-horizon-cover-v2.png",kicker:"Digital Employee · Academic Observation 003",title:"Multi-Horizon Work Needs a Runtime",summary:"Long-horizon work becomes a systems problem when many tasks coexist: ownership, scheduling, memory, failure and evidence have to become explicit runtime state.",version:"DA003",status:"Academic Runtime V5 · 2026-08-12",languageHref:"/zh/digital-employee/2026-08-12-corpgen-multi-horizon-runtime",languageLabel:"简体中文"}),e[0]||(e[0]=s('<h1 id="multi-horizon-work-needs-a-runtime-not-a-larger-context-window" tabindex="-1">Multi-Horizon Work Needs a Runtime, Not a Larger Context Window <a class="header-anchor" href="#multi-horizon-work-needs-a-runtime-not-a-larger-context-window" aria-label="Permalink to &quot;Multi-Horizon Work Needs a Runtime, Not a Larger Context Window&quot;">​</a></h1><p>A long task and many concurrent long tasks are not the same engineering problem.</p><p>A single agent can sometimes survive a longer assignment by receiving a larger context window, better summarization, or more capable models. But once dozens of tasks coexist, the runtime has to answer questions that token capacity alone cannot answer: Which task owns the next action? Which one is blocked? Which memory belongs to which objective? How should failures be bounded? What evidence is sufficient to say that one task is actually complete?</p><p>Microsoft Research&#39;s 2026 CorpGen paper, <em>Scaling Agents for Enterprise Multi-Horizon Task Execution</em>, is useful because it studies exactly this transition. The paper calls the setting <strong>Multi-Horizon Task Execution (MHTE)</strong> and evaluates an architecture that makes planning, task isolation, memory, retry behavior and evaluation explicit.</p><p>The evidence supports a bounded conclusion: <strong>concurrent long-horizon work is a runtime-coordination problem, not merely a context-length problem.</strong> The evidence does not establish that CorpGen itself is a production-ready enterprise Digital Employee runtime.</p><h2 id="what-changes-when-work-becomes-a-portfolio-of-tasks" tabindex="-1">What changes when work becomes a portfolio of tasks? <a class="header-anchor" href="#what-changes-when-work-becomes-a-portfolio-of-tasks" aria-label="Permalink to &quot;What changes when work becomes a portfolio of tasks?&quot;">​</a></h2><p>The paper&#39;s MHTE setting involves many simultaneous objectives rather than one uninterrupted trajectory. The authors describe workloads with dozens of concurrent tasks, commonly 10–30 or more operational steps per task, and aggregate horizons extending into hundreds or more than a thousand interactions.</p><p>That changes the failure surface. Context saturation is only one problem. Cross-task memory interference, dependency management, reprioritization, retries and task-local state become separate runtime concerns.</p><p>This distinction matters because a larger context window can preserve more history while still leaving the runtime without an explicit answer to a basic operational question: <strong>what is the current state of each work item?</strong></p><p>A Digital Employee that manages a portfolio of work therefore needs more than conversational continuity. It needs durable task identity, scheduling state, bounded local context and evidence about outcomes.</p><h2 id="what-the-corpgen-evidence-actually-reports" tabindex="-1">What the CorpGen evidence actually reports <a class="header-anchor" href="#what-the-corpgen-evidence-actually-reports" aria-label="Permalink to &quot;What the CorpGen evidence actually reports&quot;">​</a></h2><p>The primary study evaluates CorpGen in controlled, OSWorld-derived office workloads. The authors combine tasks into higher-load sessions, including a 46-task condition with a six-hour execution cap.</p><p>In the paper&#39;s main high-load comparison, the authors report <strong>15.2 aggregate completed tasks for CorpGen versus 4.3 for the stated UFO2 baseline</strong>. That is roughly a 3.5× relative improvement under the tested configuration.</p><p>The absolute number matters as much as the relative gain. At the hardest reported load, most tasks are still not completed. The result is evidence of improved coordination under stress; it is not evidence that the workload has been solved.</p><p>The ablation evidence also matters. In the reported 100% load condition, adding the cognitive model and tools raises the aggregate completion result to 8.7, while adding experiential learning raises it to 15.2. The source therefore attributes a material part of the gain to reuse of prior successful experience, not only to hierarchy or memory structure.</p><p>These are <strong>source-reported research results</strong> from the authors&#39; own controlled experiment. This run identified no independent reproduction of the full CorpGen result.</p><h2 id="the-architecture-is-more-transferable-than-the-headline-score" tabindex="-1">The architecture is more transferable than the headline score <a class="header-anchor" href="#the-architecture-is-more-transferable-than-the-headline-score" aria-label="Permalink to &quot;The architecture is more transferable than the headline score&quot;">​</a></h2><p>The strongest contribution is not the 3.5× number. It is the decomposition of long-horizon work into explicit runtime mechanisms.</p><h3 id="hierarchical-planning-separates-horizons" tabindex="-1">Hierarchical planning separates horizons <a class="header-anchor" href="#hierarchical-planning-separates-horizons" aria-label="Permalink to &quot;Hierarchical planning separates horizons&quot;">​</a></h3><p>CorpGen distinguishes longer-horizon objectives, daily task planning and operational actions. Planning can be updated as events occur instead of being frozen into one plan at the beginning of a run.</p><p>This matters because reprioritization becomes a first-class scheduling action. A runtime can revise which task should advance without rewriting the entire history of every other task.</p><h3 id="isolated-task-agents-bound-cross-task-interference" tabindex="-1">Isolated task agents bound cross-task interference <a class="header-anchor" href="#isolated-task-agents-bound-cross-task-interference" aria-label="Permalink to &quot;Isolated task agents bound cross-task interference&quot;">​</a></h3><p>Individual work items can execute in isolated agent contexts. This creates a cleaner ownership boundary around task-local context and reduces the chance that unrelated task histories contaminate one another.</p><p>The important idea is not that every task must have its own model instance. The important idea is that <strong>ownership of active context should follow ownership of work</strong>.</p><h3 id="tiered-memory-avoids-chronological-replay" tabindex="-1">Tiered memory avoids chronological replay <a class="header-anchor" href="#tiered-memory-avoids-chronological-replay" aria-label="Permalink to &quot;Tiered memory avoids chronological replay&quot;">​</a></h3><p>The architecture separates working memory, structured long-term memory and semantic retrieval. It retrieves relevant state instead of replaying an ever-growing chronological transcript into every decision.</p><p>That is a runtime policy choice. Memory is not simply “more context”; it is a governed decision about what state remains active, what is stored durably and what is retrieved for a specific task.</p><h3 id="retry-and-skip-make-failure-schedulable" tabindex="-1">Retry and skip make failure schedulable <a class="header-anchor" href="#retry-and-skip-make-failure-schedulable" aria-label="Permalink to &quot;Retry and skip make failure schedulable&quot;">​</a></h3><p>The implementation bounds repeated failure instead of allowing one task to consume the entire run indefinitely. After bounded unsuccessful attempts, work can be skipped and recorded as failed.</p><p>For a multi-task worker, this is essential. <code>Retrying</code>, <code>Blocked</code>, <code>Failed</code> and <code>Skipped</code> are not cosmetic labels. They determine whether unrelated work can continue.</p><h3 id="experiential-learning-reuses-successful-work" tabindex="-1">Experiential learning reuses successful work <a class="header-anchor" href="#experiential-learning-reuses-successful-work" aria-label="Permalink to &quot;Experiential learning reuses successful work&quot;">​</a></h3><p>CorpGen can retrieve prior successful trajectories for similar tasks. The mechanism uses semantic retrieval rather than updating model parameters during the run.</p><p>This is useful, but it also complicates interpretation of the experiment: some of the reported gain may depend on reusable experience from the task distribution. The result should not be reduced to “hierarchy alone solves long-horizon work.”</p><h2 id="completion-evidence-is-a-separate-problem-from-action-history" tabindex="-1">Completion evidence is a separate problem from action history <a class="header-anchor" href="#completion-evidence-is-a-separate-problem-from-action-history" aria-label="Permalink to &quot;Completion evidence is a separate problem from action history&quot;">​</a></h2><p>One of the paper&#39;s most useful methodological observations concerns evaluation.</p><p>For office tasks, the durable output artifact can sometimes tell us more about completion than the action trace. A document, spreadsheet or other resulting state can be inspected directly instead of judging whether a long sequence of clicks merely looked plausible.</p><p>The paper reports a small meta-evaluation in which artifact-based judgments aligned with human judgments much more often than screenshot/action-trace-only evidence. But that comparison covered only <strong>11 task executions</strong>. The roughly 90% versus 40% agreement figures should therefore remain bound to that tiny evaluation rather than be treated as a universal law.</p><p>The broader lesson is narrower and more defensible: <strong>completion evidence should be attached to the requested outcome, not inferred only from worker activity.</strong></p><p>That still leaves important cases unresolved. An artifact may exist while a harmful side effect also occurred. A file can be correct while the wrong account was used. A business record can be created while authorization was missing. Outcome evidence and authority evidence are not the same thing.</p><h2 id="engineering-implications-for-long-running-agent-systems" tabindex="-1">Engineering implications for long-running agent systems <a class="header-anchor" href="#engineering-implications-for-long-running-agent-systems" aria-label="Permalink to &quot;Engineering implications for long-running agent systems&quot;">​</a></h2><p>The CorpGen evidence suggests six runtime design consequences that apply beyond the specific implementation.</p><p>First, <strong>task identity should be durable state</strong>. If an item cannot be identified independently of prompt text, it cannot be safely reprioritized, retried or audited across a long run.</p><p>Second, <strong>concurrency should be partitioned by ownership</strong>. Task-local state should be isolated enough that one workstream does not silently mutate the reasoning context of another.</p><p>Third, <strong>memory needs an explicit lifecycle</strong>. Working context, durable state and semantic retrieval serve different purposes and should not collapse into one undifferentiated transcript.</p><p>Fourth, <strong>failure needs scheduling semantics</strong>. A worker should be able to say that one task is blocked or exhausted while other eligible tasks continue.</p><p>Fifth, <strong>completion should prefer durable outcome evidence where possible</strong>. Action traces remain useful for diagnosis, but activity is not completion.</p><p>Sixth, <strong>relative improvement and absolute completion should always be reported together</strong>. A system can be several times better than a baseline and still be far from reliable enough for unattended consequential work.</p><h2 id="where-the-evidence-stops" tabindex="-1">Where the evidence stops <a class="header-anchor" href="#where-the-evidence-stops" aria-label="Permalink to &quot;Where the evidence stops&quot;">​</a></h2><p>The paper is a primary research source, not independent validation of its own architecture. Several boundaries remain important.</p><p>The benchmark is constructed from controlled OSWorld Office tasks rather than longitudinal real-company work. The reported sessions are high-load and hours-long, but the main evaluation is not a multi-day deployment with credential expiry, human interruptions, changing permissions or organizational policy changes.</p><p>The study does not establish restart-safe exactly-once work semantics, transaction rollback, compensation for side effects, conflict control when concurrent tasks modify the same external resource, or an independent business acceptance authority.</p><p>The authors also identify limits around GUI reliability, state assumptions, compute overhead and the absence of ground-truth real corporate behavioral data.</p><p>None of these limitations erase the engineering value of the experiment. They define what the experiment is evidence for.</p><h2 id="what-should-be-tested-next" tabindex="-1">What should be tested next? <a class="header-anchor" href="#what-should-be-tested-next" aria-label="Permalink to &quot;What should be tested next?&quot;">​</a></h2><p>The next research step is not to ask whether one model can handle even more tokens. It is to test the runtime boundaries that the paper makes visible.</p><p>Can task identity and ownership survive process restart without duplicate consequential actions? Can a scheduler preserve fairness while priorities change continuously? Can isolated task contexts coordinate safely when they touch the same external resource? Can artifact-based completion evidence detect delayed or hidden side effects? Do the same coordination gains reproduce independently on non-OSWorld enterprise workloads?</p><p>Those questions separate a promising multi-horizon research architecture from a production Digital Employee runtime.</p><p>The useful conclusion is therefore precise: <strong>when work becomes a portfolio, the runtime must carry the portfolio as state.</strong> Context length can help an agent remember more. It cannot replace ownership, scheduling, bounded failure, durable memory and outcome evidence.</p><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ol><li>Microsoft Research / arXiv, <strong>Scaling Agents for Enterprise Multi-Horizon Task Execution</strong>, arXiv:2602.14229 — <a href="https://arxiv.org/abs/2602.14229" target="_blank" rel="noreferrer">https://arxiv.org/abs/2602.14229</a></li><li>Full paper HTML — <a href="https://arxiv.org/html/2602.14229" target="_blank" rel="noreferrer">https://arxiv.org/html/2602.14229</a></li><li>Microsoft Research, <strong>CorpGen: Scaling agents for enterprise multi-horizon task execution</strong> — <a href="https://www.microsoft.com/en-us/research/blog/corpgen-scaling-agents-for-enterprise-multi-horizon-task-execution/" target="_blank" rel="noreferrer">https://www.microsoft.com/en-us/research/blog/corpgen-scaling-agents-for-enterprise-multi-horizon-task-execution/</a></li><li>Governed Deep Reading — <code>research/reading/Q-20260803-09-corpgen-multi-horizon.md</code></li><li>Governed Research Analysis — <code>research/analysis/Q-20260803-09-corpgen-multi-horizon.md</code></li></ol>',60))])}const b=o(l,[["render",c]]);export{f as __pageData,b as default};
